function SettingBindEmailDialog:InitHandler()
    SetButtonAction(self.BtnClose, Bind(self, self.BtnCloseClickCallback))
    SetButtonAction(self.BtnCloseBack, Bind(self, self.BtnCloseClickCallback))
    SetButtonAction(self.BtnGetCode, Bind(self, self.BtnGetCodeOnClickCallback))
