--region handler
---关闭按钮点击回调
function SettingBindEmailDialog:BtnCloseClickCallback()
    UIModule.CloseDialog(self.controller)
end


---获取验证码按钮点击回调
function SettingBindEmailDialog:BtnGetCodeOnClickCallback()
    if self._cd > 0 then
        return
    end
    
    if not self:CheckBtnGetCodeStatus(true) then
        return
    end
    
    local phone = self:GetFullPhone()
    GameUtils.Request("OverseaPlayer/sendBindEmailVerifyCode", {email = phone}, Bind(self, self.SendCodeResponseHandler))
end
function SettingBindEmailDialog:GetFullPhone()
    return string.trim(self.PhoneInputField.text)
end

---检查获取验证码按钮状态
function SettingBindEmailDialog:CheckBtnGetCodeStatus(isShowTips)
    if not Utils.IsValidEmail(self:GetFullPhone()) then
        if isShowTips then
            GameUtils.Toast(localize('请输入正确的邮箱地址'))
        end
        return false
    end

    ---@type ScreenToggle
    local env = CfUtils.GetLuaScr(self.LabelGroup, Constants.UILuaTablePath.ScreenToggle)
    if env and not env.isOn then
        if isShowTips then
            GameUtils.Toast(localize('请勾选隐私协议'))
        end
        return false
    end
    
    return true
end

---确认按钮点击回调
function SettingBindEmailDialog:BtnConfirmOnClickCallback()
    local code = self.CodeInputField.text
    if string.isEmpty(code) then
        GameUtils.Toast(localize('请输入正确的验证码'))
        return
    end
    
    local phone = self:GetFullPhone()
    if string.isEmpty(phone) then
        GameUtils.Toast(localize('请输入正确的邮箱地址'))
        return
    end
    GameUtils.Request("OverseaPlayer/bindEmail", {email = phone, code = code}, Bind(self, self.BindPhoneResponseHandler))
end

---发送验证码response处理
function SettingBindEmailDialog:SendCodeResponseHandler(request, response)
    if checkNumber(response.errCode) ~= 0 then return end
    
    self._cd = VerificationCodeCD
    self:StartTimer()
end

function SettingBindEmailDialog:BindPhoneResponseHandler(request, response)
    if checkNumber(response.errCode) ~= 0 then return end
    GameUtils.SetRedPointNum(Constants.RedPointConst.OtherSettingEmailButton, -1)
    GameUtils.InvokeRedPointCallBack(Constants.RedPointConst.OtherSettingEmailButton)
    local rewards = checkTable(response.data.rewards)
    if next(rewards) then
        GoodsUtils.DrawRewards(rewards)
        UIModule.OpenDialog({ id = Constants.UITypeIds.UICommonRewardPop, parameters = { rewards = rewards } })
    else
        GameUtils.Toast(localize("订阅成功"))
    end
        
    local phone = self:GetFullPhone()
    local userComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.UserComponent)
    userComponent.userInfo.email = phone
    self._confirmCB(phone)
    UIModule.CloseDialog(self.controller)
end

---手机号输入框改变回调
function SettingBindEmailDialog:OnPhoneInputFieldChanged(text)
    self:RefreshSendVerificationCodeBtn()
    self:RefreshConfirmBtn()
end

---验证码输入框改变回调
function SettingBindEmailDialog:OnCodeInputFieldChanged(text)
    self:RefreshConfirmBtn()
end

---toggle改变回调
function SettingBindEmailDialog:OnToggleChangeHandler(isOn)
    self:RefreshSendVerificationCodeBtn()
    self:RefreshConfirmBtn()
end
