---刷新UI
function SettingBindEmailDialog:RefreshUI()
    self:RefreshSendVerificationCodeBtn()
    self:RefreshConfirmBtn()
end


---刷新发送验证码按钮
function SettingBindEmailDialog:RefreshSendVerificationCodeBtn()
    if self._cd <= 0 then
        if self:CheckBtnGetCodeStatus(false) then
            CfUtils.SetUISwitchImage(self.BtnGetCode, 1)
        else
            CfUtils.SetUISwitchImage(self.BtnGetCode, 2)
        end
        CfUtils.FillText(self.BtnGetCodeText, localize('获取验证码'))
        return
    end

    CfUtils.SetUISwitchImage(self.BtnGetCode, 2)
    CfUtils.FillText(self.BtnGetCodeText, string.format("%ds", checkInt(self._cd)))
end

---刷新确认按钮
function SettingBindEmailDialog:RefreshConfirmBtn()
    local text = nil
    if tostring(self.email) ~= '' then
        CfUtils.SetActive(self.HarvestAnim, false)
        CfUtils.SetActive(self.TextState1, false)
        CfUtils.SetActive(self.State2, true)
        CfUtils.FillText(self.TextPhoneNum, self.email)
        text = localize('确认更换')
    else
        CfUtils.SetActive(self.HarvestAnim, false)
        --local goodsId = CfUtils.GetCfVo(AutoIds.IdSetting10, "BaseArgVo", 30).num
        --local goodsNum = CfUtils.GetCfVo(AutoIds.IdSetting10, "BaseArgVo", 31).num
        --local goodsVo = GoodsConfMgr:GetInstance():GetGoodsVoById(goodsId)
        --CfUtils.FillImage(self.ImgGoodIcon, goodsVo.photoPath)
        --CfUtils.FillText(self.GoodsTxtNum, goodsNum)
        CfUtils.SetActive(self.TextState1, true)
        CfUtils.SetActive(self.State2, false)
        text = localize('确认绑定')
    end

    local code = self.CodeInputField.text
    if self:CheckBtnGetCodeStatus(false) and not string.isEmpty(code) then
        CfUtils.SetButtonStyle(self.FontStyleButton, "B3", text)
    else
        CfUtils.SetButtonStyle(self.FontStyleButton, "B17", text)
    end
end

---开启定时器
function SettingBindEmailDialog:StartTimer()
    self:StopTimer()

    self._timer =  CDTimerModule.GetInstance():AddCD(1, function(count, id, interval)
        self._cd = self._cd - interval
        self:RefreshSendVerificationCodeBtn()
    end, self._cd, true, true)

    self._timer.OnRemove =  function(count, id)
        self._cd = 0
    end
end

---关闭定时器
function SettingBindEmailDialog:StopTimer()
    if isNull(self._timer) then
        return
    end

    CDTimerModule.GetInstance():RemoveCD(self._timer)
    self._timer = nil 
end

